import{_ as t,o as s,c as e,a4 as n}from"./chunks/framework.BRzJ4ijD.js";const u=JSON.parse('{"title":"6. 并发与一致性: 单机到分布式同构","description":"","frontmatter":{},"headers":[],"relativePath":"_meta/concurrency-consistency.md","filePath":"_meta/concurrency-consistency.md","lastUpdated":1788475713000}'),l={name:"_meta/concurrency-consistency.md"};function d(o,a,i,r,p,c){return s(),e("div",null,[...a[0]||(a[0]=[n(`<h1 id="_6-并发与一致性-单机到分布式同构" tabindex="-1">6. 并发与一致性: 单机到分布式同构 <a class="header-anchor" href="#_6-并发与一致性-单机到分布式同构" aria-label="Permalink to &quot;6. 并发与一致性: 单机到分布式同构&quot;">​</a></h1><h2 id="一句话" tabindex="-1">一句话 <a class="header-anchor" href="#一句话" aria-label="Permalink to &quot;一句话&quot;">​</a></h2><p>并发与一致性是&quot;同一个故事讲了三遍&quot;的事情——它在<strong>单机多核 cache coherence</strong>、<strong>单机并发数据库事务</strong>、<strong>分布式多节点存储</strong>三个层次用几乎同样的语言复述. 这不是巧合: 它们都受同一组物理约束支配——<strong>多个 writer + 共享 state + 延迟会限制原子性的可见范围</strong>. 理解这一点, 从 MESI 学到 Paxos / Raft 就是一座平滑的桥.</p><h2 id="思想链" tabindex="-1">思想链 <a class="header-anchor" href="#思想链" aria-label="Permalink to &quot;思想链&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>工程问题: 为什么学完 MESI 再看 Raft 会觉得似曾相识?</span></span>
<span class="line"><span>  └─► 三层并发表由同一组物理约束生成</span></span>
<span class="line"><span>        └─► 多个 writer + 共享状态 + 延迟决定原子性可见范围</span></span>
<span class="line"><span>              └─► 单机多核:    共享 L3/内存, 1-50 ns     → MESI/MOESI</span></span>
<span class="line"><span>              └─► 单机多线程:  进程内存,   μs 级        → mutex/CAS/RCU</span></span>
<span class="line"><span>              └─► 跨机分布式:  网络消息,   100 μs-50 ms → Paxos/Raft/2PC</span></span>
<span class="line"><span>  └─► 角色逐行对应</span></span>
<span class="line"><span>        └─► MESI Modified ≈ Raft leader   (唯一的可写最新副本)</span></span>
<span class="line"><span>        └─► MESI Shared   ≈ Raft follower (只读同步副本)</span></span>
<span class="line"><span>        └─► Invalidate 消息 ≈ AppendEntries 复制</span></span>
<span class="line"><span>  └─► 两者的全部差异来自信道可靠性</span></span>
<span class="line"><span>        └─► 铜互联不丢包、延迟确定 → 协议可以极简</span></span>
<span class="line"><span>        └─► 网络会丢包、分区、乱序 → 必须加 quorum / term / 选主</span></span></code></pre></div><h2 id="三层并发表" tabindex="-1">三层并发表 <a class="header-anchor" href="#三层并发表" aria-label="Permalink to &quot;三层并发表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层</th><th>writers</th><th>共享 state</th><th>介质延迟</th><th>一致性机制</th></tr></thead><tbody><tr><td>单机多核</td><td>2-100 核</td><td>L1/L2/L3 cache</td><td>1-50 ns</td><td>MESI / MOESI / MESIF</td></tr><tr><td>单机多线程</td><td>10-1000 线程</td><td>进程内存</td><td>1-2 μs (lock 获取)</td><td>mutex / CAS / seqlock / <a href="./../os/lock/rcu">RCU</a></td></tr><tr><td>单机多进程</td><td>进程级</td><td>mmap / SysV shm</td><td>5-10 μs (syscall)</td><td>futex / shared memory + atomic</td></tr><tr><td>跨机分布式</td><td>N 台机器</td><td>网络消息</td><td>100 μs - 50 ms</td><td>Paxos / Raft / 2PC / 3PC</td></tr></tbody></table><p>最关键的观察: <strong>本机多核协议和分布式共识协议做的是同一件事——读、写、半数确认</strong>; 主要差别在 latency budget 和 failure mode.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>单机侧的原语实现见 <a href="./../os/lock/futex-cas">futex、CAS、spinlock 内部</a> 与 <a href="./../os/lock/lockfree">lock-free/wait-free 数据结构</a>; 分布式侧见 <a href="./../distributed/consensus/paxos">Paxos / Multi-Paxos</a> 与 <a href="./../distributed/consensus/raft">Raft 详解</a>. 对照着读, 你会发现术语表几乎可以逐行翻译.</p></div><h2 id="强一致性-vs-弱一致性-vs-最终一致性" tabindex="-1">强一致性 vs 弱一致性 vs 最终一致性 <a class="header-anchor" href="#强一致性-vs-弱一致性-vs-最终一致性" aria-label="Permalink to &quot;强一致性 vs 弱一致性 vs 最终一致性&quot;">​</a></h2><p>强一致性: 一次操作要么全部可见, 要么全不可见 (linearizable).</p><ul><li>MESI 在单机上提供强一致: 一个核修改时, 其他核的副本被 invalidate;</li><li>单机数据库事务在 transaction 内部强一致;</li><li>Paxos / Raft 提供 linearizable 共识 (一次写入需多数节点 ack);</li><li>Spanner 通过 TrueTime 提供外部一致性 (external consistency).</li></ul><p>弱一致性: 读可能读到过期值.</p><ul><li>缓存允许短暂不一致, 以换取吞吐;</li><li>Dynamo/S3 风格的最终一致性: 在 read repair 等反熵修复后系统收敛.</li></ul><p><strong>CAP 定理告诉我们</strong>: 分区发生时不能同时强一致 + 可用 (<a href="./../distributed/concepts/cap">CAP / PACELC / BASE</a>). 单机几乎没有 partition, 但分布式里 partition 不可避免——这是单机 ↔ 分布式抽象差异最大之处.</p><h2 id="抽象的桥梁" tabindex="-1">抽象的桥梁 <a class="header-anchor" href="#抽象的桥梁" aria-label="Permalink to &quot;抽象的桥梁&quot;">​</a></h2><p>单机 MESI 看似陌生, 但<strong>逻辑上与 Raft 同构</strong>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>MESI M (modified)   ≈ Raft leader   (持有最新未下刷数据)</span></span>
<span class="line"><span>MESI S (shared)     ≈ Raft follower (持有已同步数据)</span></span>
<span class="line"><span>MESI invalidate msg ≈ Raft AppendEntries</span></span>
<span class="line"><span>MESI BusRd / snoop  ≈ follower 的 ReadIndex 读请求</span></span></code></pre></div><p><strong>两边都是&quot;中心控制点 + 多 reader + 状态同步消息&quot;</strong>. Raft 用网络消息实现 MESI 式的同步; MESI 用总线仲裁实现类似 leader/follower 的同步.</p><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>同构有助于理解, 但不要把工程参数也照搬. MESI 的 invalidate 在芯片内是纳秒级且不会丢失, 所以硬件敢用&quot;广播 + 等待确认&quot;; 分布式系统的消息会丢、会延迟抖动, 所以必须补上任期号、多数派和幂等日志——把 MESI 直译成网络协议, 得到的是一个会被一张乱序报文打崩的系统. 不可靠信道带来的额外机制见 <a href="./../distributed/consensus/raft">Raft 详解</a>.</p></div><h2 id="锁、cas、事务的对应" tabindex="-1">锁、CAS、事务的对应 <a class="header-anchor" href="#锁、cas、事务的对应" aria-label="Permalink to &quot;锁、CAS、事务的对应&quot;">​</a></h2><p>继续对比:</p><table tabindex="0"><thead><tr><th>抽象</th><th>单机实现</th><th>分布式等价</th></tr></thead><tbody><tr><td>单点锁</td><td>mutex</td><td>leader 租约锁服务 (ZooKeeper ephemeral node)</td></tr><tr><td>CAS 一致</td><td>atomic cmpxchg</td><td>Cassandra LWT (lightweight transactions)</td></tr><tr><td>事务 prepare/commit</td><td>数据库本地 2PC</td><td>跨库 XA / Saga</td></tr><tr><td>Quorum</td><td>多核总线仲裁</td><td>quorum read/write, W + R &gt; N</td></tr><tr><td>快照隔离</td><td>MVCC (PostgreSQL)</td><td>Spanner snapshot / CockroachDB</td></tr></tbody></table><h2 id="工程转折点-延迟预算让-乐观算法-赢" tabindex="-1">工程转折点: 延迟预算让&quot;乐观算法&quot;赢 <a class="header-anchor" href="#工程转折点-延迟预算让-乐观算法-赢" aria-label="Permalink to &quot;工程转折点: 延迟预算让&quot;乐观算法&quot;赢&quot;">​</a></h2><p>当 latency = 1-50 ns 时:</p><ul><li>总线锁定与阻塞等待代价小;</li><li><strong>悲观锁</strong>通常性能更好 (低延迟, 但牺牲吞吐).</li></ul><p>当 latency = 1-100 ms 时:</p><ul><li>锁的 ack 要等一个 RTT, 阻塞代价巨大;</li><li><strong>乐观并发</strong> (MVCC + 只读事务不阻塞) 表现更优;</li><li>这就是为什么现代数据库 Spanner / CockroachDB / TiKV 都选 MVCC + Raft.</li></ul><p>这就是&quot;跨越延迟量级后, 并发模型必须从悲观切换到乐观&quot;——同一抽象在不同 latency budget 下换载体. 单机侧的 MVCC 实现对照见 <a href="./../databases/relational/mvcc">MVCC 原理: PostgreSQL vs InnoDB</a>.</p><h2 id="各语言的同构并发原语" tabindex="-1">各语言的同构并发原语 <a class="header-anchor" href="#各语言的同构并发原语" aria-label="Permalink to &quot;各语言的同构并发原语&quot;">​</a></h2><p>各语言层级的并发原语抽象基本相同:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mutex:   C++ std::mutex / Rust std::sync::Mutex / Go sync.Mutex / Java synchronized / Python threading.Lock</span></span>
<span class="line"><span>rwlock:  各语言的 shared_mutex / RWMutex 对应版本</span></span>
<span class="line"><span>cond:    std::condition_variable / sync.Cond / Java wait-notify / Python Condition</span></span>
<span class="line"><span>futex:   Linux futex syscall —— 现代几乎所有用户态 mutex 的底层</span></span>
<span class="line"><span>atomic:  std::atomic&lt;T&gt; / Rust AtomicXxx / Go sync/atomic / Java AtomicInteger</span></span>
<span class="line"><span>channel: Go channel (CSP) / Rust std::sync::mpsc / Clojure core.async / Java Disruptor</span></span></code></pre></div><p>这些原语在不同语言里的语义基本一致, 这是&quot;工程师可以在语言之间迁移&quot;的基础. 但<strong>语言选择把权重放在哪个原语上</strong> (Go 押 channel; C++ 押 atomic/mutex; Python 受 GIL 制约) 只是侧重不同, 不是语义差异. 内存序层面的坑则统一由 <a href="./../os/lock/memory-barrier">内存模型与 memory barrier</a> 兜底.</p><h2 id="一致性实验-多线程累加器" tabindex="-1">一致性实验: 多线程累加器 <a class="header-anchor" href="#一致性实验-多线程累加器" aria-label="Permalink to &quot;一致性实验: 多线程累加器&quot;">​</a></h2><p>考虑一个最小一致性问题: 多线程累加. 三个方案:</p><h3 id="方案-1-mutex-累加" tabindex="-1">方案 1: mutex 累加 <a class="header-anchor" href="#方案-1-mutex-累加" aria-label="Permalink to &quot;方案 1: mutex 累加&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sum = 0; mutex m;</span></span>
<span class="line"><span>并行循环: 持有 m 后 sum += x;</span></span>
<span class="line"><span>吞吐: ~20M ops/s (4 核激烈争用下锁成为串行点)</span></span></code></pre></div><h3 id="方案-2-cas-失败重试" tabindex="-1">方案 2: CAS 失败重试 <a class="header-anchor" href="#方案-2-cas-失败重试" aria-label="Permalink to &quot;方案 2: CAS 失败重试&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>std::atomic&lt;long&gt; sum;</span></span>
<span class="line"><span>循环: expected = sum.load();</span></span>
<span class="line"><span>      if (sum.compare_exchange_weak(expected, expected + x)) break;</span></span>
<span class="line"><span>吞吐: 高竞争下重试风暴 → ~10M ops/s, 且延迟方差更大</span></span></code></pre></div><h3 id="方案-3-thread-local-结束时合并" tabindex="-1">方案 3: thread-local + 结束时合并 <a class="header-anchor" href="#方案-3-thread-local-结束时合并" aria-label="Permalink to &quot;方案 3: thread-local + 结束时合并&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>thread_local long local_sum = 0;</span></span>
<span class="line"><span>并行循环: local_sum += x;          // 无共享, 无争用</span></span>
<span class="line"><span>线程结束时: 加锁一次性合并进全局 sum</span></span>
<span class="line"><span>吞吐: ~500M ops/s</span></span></code></pre></div><p>三种方案语义等价, 但<strong>实测常数差出 25× 以上</strong>. 这就是为什么 <strong>&quot;减少争用 + 分片 + thread-local&quot; 是并发的第一技术</strong>, 而&quot;换更快的原子原语&quot;只是第二梯队.</p><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>判断并发优化方向先看争用面, 再换原语: 先问&quot;这份数据能不能变成 per-thread / per-shard&quot;, 再问&quot;锁能不能换成 CAS&quot;, 最后才轮到&quot;换个更快的锁&quot;. 内核里把这套思路推到极致的是 RCU——读者完全无锁, 见 <a href="./../os/lock/rcu">RCU、seqlock、brlock</a>.</p></div><h2 id="这一章带走的东西" tabindex="-1">这一章带走的东西 <a class="header-anchor" href="#这一章带走的东西" aria-label="Permalink to &quot;这一章带走的东西&quot;">​</a></h2><ul><li>单机多核 MESI 与分布式 Raft 在抽象上同构;</li><li>一致性等级从强一致 (linearizable) 到最终一致;</li><li>CAP 只在分布式层咬人: 单机没有 partition, 弱约束不构成威胁;</li><li>并发模型选悲观还是乐观, 由 latency budget 决定;</li><li>&quot;减小争用 + thread-local&quot;比原子原语本身的快慢更重要.</li></ul><h2 id="一页速查" tabindex="-1">一页速查 <a class="header-anchor" href="#一页速查" aria-label="Permalink to &quot;一页速查&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>单机多核 (MESI)</th><th>单机多线程 (锁/MVCC)</th><th>分布式 (Paxos/Raft)</th></tr></thead><tbody><tr><td>共享介质</td><td>cache line / 总线</td><td>进程内存</td><td>网络 RTT</td></tr><tr><td>延迟量级</td><td>1-50 ns</td><td>1-10 μs</td><td>100 μs - 50 ms</td></tr><tr><td>排他权获取</td><td>RFO 总线事务</td><td>mutex / cmpxchg</td><td>选主 (RequestVote)</td></tr><tr><td>数据传播</td><td>snoop / directory 广播</td><td>直接读写共享内存</td><td>AppendEntries 复制</td></tr><tr><td>冲突仲裁</td><td>总线优先级</td><td>锁队列</td><td>term 单调递增</td></tr><tr><td>故障模型</td><td>不丢消息, 无拜占庭</td><td>线程崩溃需进程兜底</td><td>丢包 / 分区 / 时钟漂移</td></tr><tr><td>典型妥协</td><td>性能核心绑定</td><td>MVCC 快照隔离</td><td>最终一致 + read repair</td></tr></tbody></table><p>下一篇: <a href="./hardware-shapes-software">7. 推理链: 硬件层如何决定软件设计</a></p>`,48)])])}const m=t(l,[["render",d]]);export{u as __pageData,m as default};
